package com.codepilot1c.core.tools.bsl;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
import com.codepilot1c.core.edt.lang.*;import com.codepilot1c.core.edt.ast.*;import com.google.gson.*;
public class BslMethodBatchTest {
 private Map<String,Object> item(String name){return Map.of("filePath","CommonModules/Orders/Module.bsl","name",name);}
 private Map<String,Object> args(List<?> items){return Map.of("projectName","OwnedFixture","items",items);}
 private BslMethodBodyResult body(BslMethodBodyRequest r,String text){return new BslMethodBodyResult(r.getProjectName(),r.getFilePath(),r.getName(),"procedure",10,20,text);}
 @Test public void exactBodiesAndOrder(){var out=BslMethodBatch.read(args(List.of(item("A"),item("B"))),r->body(r,r.getName()));assertTrue(out.get("complete").getAsBoolean());assertEquals("B",out.getAsJsonArray("items").get(1).getAsJsonObject().getAsJsonObject("method").get("text").getAsString());assertEquals(2,out.get("returned_body_chars").getAsInt());assertFalse(out.get("atomic_snapshot").getAsBoolean());}
 @Test public void sharedCapIncludesMarkers(){var out=BslMethodBatch.read(Map.of("projectName","OwnedFixture","max_chars",2000,"items",Collections.nCopies(8,item("A"))),r->body(r,"😀".repeat(10000)));assertTrue(out.get("returned_body_chars").getAsInt()<=2000);assertEquals(8,out.get("truncated_items").getAsInt());assertFalse(out.get("complete").getAsBoolean());for(var v:out.getAsJsonArray("items")){String t=v.getAsJsonObject().getAsJsonObject("method").get("text").getAsString();for(int i=0;i<t.length();i++){if(Character.isHighSurrogate(t.charAt(i))){assertTrue(i+1<t.length()&&Character.isLowSurrogate(t.charAt(++i)));}else assertFalse(Character.isLowSurrogate(t.charAt(i)));}}}
 @Test public void itemErrorDoesNotHideOtherReads(){var out=BslMethodBatch.read(args(List.of(item("bad"),item("ok"))),r->{if(r.getName().equals("bad"))throw new EdtAstException(EdtAstErrorCode.FILE_NOT_FOUND,"not found",false);return body(r,"yes");});assertEquals(1,out.get("failed_items").getAsInt());assertFalse(out.get("complete").getAsBoolean());assertTrue(out.getAsJsonArray("items").get(1).getAsJsonObject().get("success").getAsBoolean());}
 @Test public void invalidLaterItemPreventsAllReads(){AtomicInteger n=new AtomicInteger();try{BslMethodBatch.read(args(List.of(item("A"),Map.of("filePath","x"))),r->{n.incrementAndGet();return body(r,"a");});fail();}catch(IllegalArgumentException ok){}assertEquals(0,n.get());}
 @Test public void rejectsShapesAndScopeOverride(){for(Object bad:List.of(List.of(),Collections.nCopies(9,item("A")),List.of("x"),List.of(Map.of("filePath","x","name","a","projectName","other")))){try{BslMethodBatch.read(Map.of("projectName","P","items",bad),r->body(r,""));fail();}catch(IllegalArgumentException ok){}}}
 @Test public void rejectsSingletonMix(){var a=new HashMap<>(args(List.of(item("A"))));a.put("filePath","x");try{BslMethodBatch.read(a,r->body(r,""));fail();}catch(IllegalArgumentException ok){}}
 @Test public void rejectsInvalidBudgets(){for(Object v:List.of(0,1999,40001,2500.5,"2000",Double.NaN)){try{BslMethodBatch.read(Map.of("projectName","P","items",List.of(item("A")),"max_chars",v),r->body(r,""));fail();}catch(IllegalArgumentException ok){}}}
 @Test public void preciseLookupArgumentsPreserved(){var out=BslMethodBatch.read(args(List.of(Map.of("filePath","src/CommonModules/X/Module.bsl","name","Run","kind","function","start_line",42,"context_lines",3))),r->{assertEquals("CommonModules/X/Module.bsl",r.getFilePath());assertEquals(Integer.valueOf(42),r.getStartLine());assertEquals(3,r.getContextLines());assertEquals("function",r.normalizedKind());return body(r,"x");});assertTrue(out.get("complete").getAsBoolean());}
 @Test public void invalidItemNumbersRejected(){for(Object value:List.of(-1,1.5,"1")){try{BslMethodBatch.read(args(List.of(Map.of("filePath","x","name","a","start_line",value))),r->body(r,"x"));fail();}catch(IllegalArgumentException ok){}}}
 @Test public void errorsBoundedAndNullBodyExplicit(){var out=BslMethodBatch.read(args(List.of(item("A"),item("B"))),r->{if(r.getName().equals("A"))throw new IllegalStateException("x".repeat(10000));return null;});assertEquals(2,out.get("failed_items").getAsInt());assertEquals(512,out.getAsJsonArray("items").get(0).getAsJsonObject().getAsJsonObject("error").get("message").getAsString().length());}
 @Test public void toolBatchAndSingletonRemainDistinct(){var service=new BslSemanticService(){@Override public BslMethodBodyResult getMethodBody(BslMethodBodyRequest r){return body(r,"test");}};var tool=new BslGetMethodBodyTool(service);var batch=tool.execute(args(List.of(item("A")))).join();assertTrue(batch.isSuccess());assertNotNull(batch.getStructuredData());var single=tool.execute(Map.of("projectName","P","filePath","x","name","A")).join();assertTrue(single.isSuccess());assertEquals("test",JsonParser.parseString(single.getContent()).getAsJsonObject().get("text").getAsString());}
}
